def pre(unit_cents, qty):
    return (unit_cents >= 1) and (unit_cents <= 500) and (qty >= 1) and (qty <= 200)

def post(unit_cents, qty, result):
    gross = unit_cents * qty
    if qty >= 100:
        pct = 15
    elif qty >= 50:
        pct = 10
    else:
        pct = 0
    expected = gross - (gross * pct) // 100
    return result == expected
